package com.pandinila.broadband_management.controller;
import com.pandinila.broadband_management.entity.*;import com.pandinila.broadband_management.service.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/customers") public class CustomerController {private final CustomerService customers;private final MonitoringService monitoring;private final IncidentService incidents;public CustomerController(CustomerService c,MonitoringService m,IncidentService i){customers=c;monitoring=m;incidents=i;}@GetMapping public List<Customer> all(){return customers.all();}@GetMapping("/{id}") public Map<String,Object> one(@PathVariable Long id){Customer c=customers.one(id);return Map.of("customer",c,"latestMetric",monitoring.latestMetric(c).orElse(null),"quality",monitoring.latestQuality(c).orElse(null),"prediction",monitoring.latestPrediction(c).orElse(null),"history",monitoring.history(c));}@PostMapping @ResponseStatus(HttpStatus.CREATED) public Customer create(@Valid @RequestBody Customer c){return customers.save(c);}@PutMapping("/{id}") public Customer update(@PathVariable Long id,@Valid @RequestBody Customer c){Customer existing=customers.one(id);c.setCustomerId(existing.getCustomerId());return customers.save(c);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){customers.delete(id);}@PostMapping("/{id}/incidents/proactive") @ResponseStatus(HttpStatus.CREATED) public Incident proactive(@PathVariable Long id){return incidents.createProactive(id);}}
